WITH base AS (SELECT *, LEAST(revenue, units) least_revenue_units FROM store_sales WHERE sale_date > DATE '2023-06-14'), latest AS (SELECT *, RANK() OVER (PARTITION BY product_id, store_id ORDER BY revenue DESC NULLS FIRST) AS rn FROM base QUALIFY rn = 1), latest_store_sales AS (SELECT id, product_id, units, rn FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY least_revenue_units DESC, id) AS rn_2 FROM latest) ranked WHERE rn_2 = 1), scored AS (SELECT id, rn, LAG(units) OVER (PARTITION BY product_id ORDER BY units, id) prev_units, LEAD(units) OVER (PARTITION BY product_id ORDER BY units, id) next_units, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY units, id) event_seq, DENSE_RANK() OVER (PARTITION BY product_id ORDER BY units DESC) units_dense_rank FROM latest_store_sales WHERE rn != 1), enriched AS (SELECT *, MAX(next_units) OVER (ORDER BY units_dense_rank, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_max_next_units, COUNT(next_units) OVER (ORDER BY units_dense_rank, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_count_next_units, SUM(next_units) OVER (ORDER BY units_dense_rank, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_sum_next_units FROM scored) SELECT id, next_units, event_seq, units_dense_rank, running_max_next_units, running_sum_next_units FROM enriched ORDER BY running_max_next_units DESC NULLS LAST
